head.script:
// 조회: 거래 ID로 부른다
scwin.fnSearch = function() {
    ShopJS.svr.doRequestAjax("ORD0100M01S", {
        data : {"orderVO" : dmaSearch.getJSON()}
    });
};

// 저장
scwin.fnSave = function() {
    ShopJS.svr.doRequestAjax( 'ORD0100M02U', { data : {} });
};

// 서버에 없는 거래: 사실 그대로 "못 찾음"으로 남아야 한다
scwin.fnPrint = function() {
    ShopJS.svr.doRequestAjax("ORD0100M09S", {});
};

// 거래 ID를 변수로 넘김: 잇지 않는다
scwin.fnCommon = function(tranId) {
    ShopJS.svr.doRequestAjax(tranId, {});
};

// 지워 둔 옛 호출: 잇지 않는다
// ShopJS.svr.doRequestAjax("ORD0100M03D", {});
/* ShopJS.svr.doRequestAjax("ORD0100M03D", {}); */

// 상세 팝업
scwin.fnPopup = function() {
    WebSquare.util.openPopup("/shop/ui/order/OrderPopup.xml?mode=view", {});
};
